require_once __DIR__.'/../includes/helpers.php'; require_role('archaeologist'); $title=localized('إضافة تقييم ميداني','Add Field Assessment'); $report_id=(int)($_GET['report_id']??0); $site_id=(int)($_GET['site_id']??0); $site=fetch_one('SELECT * FROM ae_heritage_sites WHERE id=?',[$site_id]); if(!$site){flash('warning',localized('الموقع غير موجود.','Site not found.'));redirect('archaeologist/tasks.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf(); $p=compute_assessment_percentage($_POST); $level=risk_level_from_percentage($p);
  query('INSERT INTO ae_field_assessments(report_id,site_id,archaeologist_id,visit_date,risk_type,damage_severity,risk_probability,spread_speed,affected_area,heritage_impact,urgency_level,risk_percentage,risk_level,notes,recommendations,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,"submitted")',[$report_id?:null,$site_id,current_user()['id'],$_POST['visit_date'],trim($_POST['risk_type']),(int)$_POST['damage_severity'],(int)$_POST['risk_probability'],(int)$_POST['spread_speed'],(int)$_POST['affected_area'],(int)$_POST['heritage_impact'],(int)$_POST['urgency_level'],$p,$level,trim($_POST['notes']),trim($_POST['recommendations'])]);
  $aid=db()->insert_id; foreach(upload_files('images','assessments') as $img) query('INSERT INTO ae_assessment_images(assessment_id,image_path) VALUES(?,?)',[$aid,$img]); if($report_id) query("UPDATE ae_incident_reports SET status='under_review' WHERE id=?",[$report_id]); flash('success',localized('تم إرسال التقييم للمسؤول للمراجعة.','Assessment submitted to the administrator for review.')); redirect('archaeologist/assessments.php');
}
include __DIR__.'/../includes/header.php';
